//! Unit 2.2 commit 4: generated Go vs the hand-written Go types.
//!
//! Fixtures are real aimux-core values serialized with serde (the Rust wire
//! is the truth). Each fixture goes through the generated Go
//! (`emit::go`) and the hand-written `bindings/go/types.go` /
//! `multimodal_types.go` (copied into a scratch module, never modified):
//! decode, then marshal. The two outputs are compared key by key.
//!
//! - `docs/plan/2.2-diff-go.md` is generated by this test and must equal the
//!   committed file (`AIMUX_BLESS_DIFF=1` rewrites it), like `--check`.
//! - Verdicts live in `docs/plan/2.2-diff-go-verdicts.json` (read with
//!   serde_json): entries `{type, field, verdict, reason}`. A diff row
//!   without a verdict, an orphan verdict, a verdict that contradicts the
//!   Rust output, or an entry without a `reason` fails.
//! - The generated Go must reproduce the Rust output exactly (no generator
//!   bug may remain).
//! - Real `go` is required: if it is missing the test fails.

#[path = "common/go_fixtures.rs"]
mod go_fixtures;

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};
use std::process::Command;

use aimux_codegen::emit::{Emitter, go::Go};
use aimux_codegen::manifest::Inputs;
use aimux_codegen::wire;
use serde_json::{Value, json};

use aimux_core::image_model::{ImageOutputs, ImageResponse, ImageResult, ImageUsage};
use aimux_core::message::{ModelMessage, Role};
use aimux_core::openai_output::{
    ChatCompletion, ChatCompletionChoice, ChatCompletionChunk, ChatCompletionChunkChoice,
    ChatCompletionDelta, ChatCompletionFunction, ChatCompletionMessage, ChatCompletionToolCall,
    ChatCompletionUsage, PromptTokensDetails,
};
use aimux_core::options::TimeoutConfiguration;
use aimux_core::tool::ToolCall;
use aimux_core::trace::{Fingerprint, RequestCacheHints, TraceRecord, UsageSnapshot};
use aimux_core::types::{
    FinishReason, FinishReasonUnified, InputTokenUsage, OutputTokenUsage, ResponseMetadata, Usage,
};

fn workspace() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// serde decode of a JSON value as the fixture's Rust type, re-serialized:
/// checks the Go → Rust direction (the generated Go's output is accepted by
/// serde and means the same value).
pub type Back = fn(&Value) -> Result<Value, String>;

/// [`Back`] for a `Deserialize` aimux-core type.
///
/// # Errors
///
/// serde rejects the value.
pub fn back<T: serde::Serialize + serde::de::DeserializeOwned>(v: &Value) -> Result<Value, String> {
    let t: T = serde_json::from_value(v.clone()).map_err(|e| e.to_string())?;
    serde_json::to_value(&t).map_err(|e| e.to_string())
}

/// One fixture: label, Go type name (same in both packages), serde output.
struct Fixture {
    label: &'static str,
    ty: &'static str,
    json: Value,
    back: Option<Back>,
}

fn fx<T: serde::Serialize>(label: &'static str, ty: &'static str, v: &T) -> Fixture {
    Fixture {
        label,
        ty,
        json: serde_json::to_value(v).expect("serde serializes the aimux-core value"),
        back: None,
    }
}

/// [`fx`] for a type that also implements `Deserialize`.
fn fxd<T: serde::Serialize + serde::de::DeserializeOwned>(
    label: &'static str,
    ty: &'static str,
    v: &T,
) -> Fixture {
    Fixture {
        back: Some(back::<T>),
        ..fx(label, ty, v)
    }
}

