/// Fixtures for generated types with no hand-written counterpart, run
/// through the generated Go only: a tri-state field (absent / null /
/// present), and two proxied types (`from`/`into` = `AiMuxErrorWire`,
/// `into`/`try_from` = `String`).
fn gen_only_fixtures() -> Vec<Fixture> {
    use aimux_core::error::AiMuxError;
    use aimux_core::evaluation_model::{BooleanCriteria, EvaluationInput};
    use aimux_core::shared::Size;
    vec![
        fxd(
            "tri-state-absent",
            "BooleanCriteria",
            &BooleanCriteria {
                true_: None,
                false_: None,
            },
        ),
        fxd(
            "tri-state-null",
            "BooleanCriteria",
            &BooleanCriteria {
                true_: Some(None),
                false_: None,
            },
        ),
        fxd(
            "tri-state-present",
            "BooleanCriteria",
            &BooleanCriteria {
                true_: Some(Some(EvaluationInput::Text("yes".into()))),
                false_: Some(None),
            },
        ),
        fxd(
            "proxy-aimux-error",
            "AiMuxError",
            &AiMuxError::NoSuchTool {
                tool_name: "search".into(),
                available_tools: Some(vec!["get_weather".into()]),
                tool_input: None,
            },
        ),
        fxd(
            "proxy-size",
            "Size",
            &Size::try_from("1024x768".to_string()).unwrap(),
        ),
    ]
}

/// Type names declared at the top level of a Go file: single `type X ...`
/// lines and the specs of grouped `type ( ... )` declarations.
fn go_type_names(src: &str) -> BTreeSet<String> {
    let first = |l: &str| l.split([' ', '\t', '[']).next().map(str::to_string);
    let mut names = BTreeSet::new();
    let mut grouped = false;
    for l in src.lines() {
        if grouped {
            if l.starts_with(')') {
                grouped = false;
            } else if let Some(spec) = l.strip_prefix('\t') {
                // Only a spec at the group's own indent, not a nested field.
                if !spec.starts_with(['\t', ' ', '/', '}']) && !spec.is_empty() {
                    names.extend(first(spec));
                }
            }
        } else if l.trim_end() == "type (" {
            grouped = true;
        } else if let Some(spec) = l.strip_prefix("type ") {
            names.extend(first(spec));
        }
    }
    names
}

#[test]
fn go_type_names_counts_single_and_grouped_declarations() {
    let src = "package x\n\ntype A struct {\n\tF int\n}\n\ntype (\n\t// B doc.\n\tB string\n\tC[T any] struct {\n\t\tV T\n\t}\n\tD = A\n)\n\ntype E[T any] []T\n";
    assert_eq!(
        go_type_names(src),
        ["A", "B", "C", "D", "E"].map(String::from).into()
    );
}

/// Types declared by the hand-written Go (`types.go` + `multimodal_types.go`).
fn hand_types() -> BTreeSet<String> {
    let dir = workspace().join("bindings/go");
    let mut out = BTreeSet::new();
    for f in ["types.go", "multimodal_types.go"] {
        out.extend(go_type_names(
            &std::fs::read_to_string(dir.join(f)).unwrap(),
        ));
    }
    out
}

/// IR type names (the generated Go's top-level types, excluding variant
/// payload structs).
fn generated_types() -> BTreeSet<String> {
    wire::from_inputs(&Inputs::from_workspace(&workspace()))
        .unwrap()
        .types
        .into_iter()
        .map(|t| t.name)
        .collect()
}

/// Hand-written types with a generated counterpart that no fixture has as
/// its root type.
fn uncovered(fixtures: &[Fixture]) -> Vec<String> {
    let gen_t = generated_types();
    hand_types()
        .into_iter()
        .filter(|t| gen_t.contains(t))
        .filter(|t| !fixtures.iter().any(|f| f.ty == t))
        .collect()
}

/// Output of one fixture through both Go type sets.
#[derive(serde::Deserialize, Debug)]
struct GoResult {
    label: String,
    gen_out: Option<Value>,
    hand_out: Option<Value>,
    gen_err: String,
    hand_err: String,
}

#[derive(serde::Deserialize, Debug)]
struct GoRun {
    results: Vec<GoResult>,
    /// `ImageResult.Images.Variant` chosen by the generated Go per label.
    variants: BTreeMap<String, String>,
}

fn copy_go(from: &Path, to: &Path, package_from: &str, package_to: &str) {
    let text = std::fs::read_to_string(from).unwrap();
    std::fs::write(
        to,
        text.replacen(
            &format!("package {package_from}"),
            &format!("package {package_to}"),
            1,
        ),
    )
    .unwrap();
}

/// Build the harness module and run it with real `go`. `mutate` edits the
/// generated types.go before the run.
fn run_go(label: &str, fixtures: &[Fixture], mutate: impl Fn(String) -> String) -> GoRun {
    let dir = std::env::temp_dir().join(format!("aimux-wire-diff-{label}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    for d in ["gen", "hand"] {
        std::fs::create_dir_all(dir.join(d)).unwrap();
    }
    std::fs::write(dir.join("go.mod"), "module harness\n\ngo 1.24\n").unwrap();
    let model = wire::from_inputs(&Inputs::from_workspace(&workspace())).unwrap();
    for o in Go.emit(&model) {
        if o.path.as_os_str() == "go.mod" {
            continue;
        }
        let content = if o.path.as_os_str() == "types.go" {
            mutate(o.content)
        } else {
            o.content
        };
        std::fs::write(dir.join("gen").join(&o.path), content).unwrap();
    }
    let bindings = workspace().join("bindings/go");
    for f in ["types.go", "multimodal_types.go"] {
        copy_go(
            &bindings.join(f),
            &dir.join("hand").join(f),
            "aimux",
            "hand",
        );
    }
    // types.go names RepairToolCallFunc (repair.go needs cgo); a stub type
    // keeps the copy compiling. It is `json:"-"` and never on the wire.
    std::fs::write(
        dir.join("hand/stub.go"),
        "package hand\n\n// RepairToolCallFunc stands in for bindings/go/repair.go (cgo).\ntype RepairToolCallFunc func()\n",
    )
    .unwrap();
    let hand = hand_types();
    let mut cases = String::new();
    for t in fixtures.iter().map(|f| f.ty).collect::<BTreeSet<_>>() {
        if hand.contains(t) {
            cases.push_str(&format!(
                "\t\tcase {t:?}:\n\t\t\tr = run[gen.{t}, hand.{t}](f.Label, f.JSON)\n"
            ));
        } else {
            cases.push_str(&format!(
                "\t\tcase {t:?}:\n\t\t\tr = result{{Label: f.Label}}\n\t\t\tr.GenOut, r.GenErr = through[gen.{t}](f.JSON)\n"
            ));
        }
    }
    let main = format!(
        r#"package main

import (
	"encoding/json"
	"os"

	gen "harness/gen"
	"harness/hand"
)

type fixture struct {{
	Label string          `json:"label"`
	Type  string          `json:"type"`
	JSON  json.RawMessage `json:"json"`
}}

type result struct {{
	Label   string          `json:"label"`
	GenOut  json.RawMessage `json:"gen_out"`
	HandOut json.RawMessage `json:"hand_out"`
	GenErr  string          `json:"gen_err"`
	HandErr string          `json:"hand_err"`
}}

func through[T any](in []byte) (json.RawMessage, string) {{
	var v T
	if err := json.Unmarshal(in, &v); err != nil {{
		return nil, "decode: " + err.Error()
	}}
	out, err := json.Marshal(v)
	if err != nil {{
		return nil, "encode: " + err.Error()
	}}
	return out, ""
}}

func run[G any, H any](label string, in []byte) result {{
	r := result{{Label: label}}
	r.GenOut, r.GenErr = through[G](in)
	r.HandOut, r.HandErr = through[H](in)
	return r
}}

func main() {{
	var fixtures []fixture
	data, err := os.ReadFile("fixtures.json")
	if err != nil {{
		panic(err)
	}}
	if err := json.Unmarshal(data, &fixtures); err != nil {{
		panic(err)
	}}
	out := struct {{
		Results  []result         `json:"results"`
		Variants map[string]string `json:"variants"`
	}}{{Variants: map[string]string{{}}}}
	for _, f := range fixtures {{
		var r result
		switch f.Type {{
{cases}		default:
			panic("no Go type for " + f.Type)
		}}
		out.Results = append(out.Results, r)
		if f.Type == "ImageResult" {{
			var g gen.ImageResult
			if json.Unmarshal(f.JSON, &g) == nil {{
				out.Variants[f.Label] = g.Images.Variant
			}}
		}}
	}}
	if err := json.NewEncoder(os.Stdout).Encode(out); err != nil {{
		panic(err)
	}}
}}
"#
    );
    std::fs::write(dir.join("main.go"), main).unwrap();
    let fixtures_json: Vec<Value> = fixtures
        .iter()
        .map(|f| json!({"label": f.label, "type": f.ty, "json": f.json}))
        .collect();
    std::fs::write(
        dir.join("fixtures.json"),
        serde_json::to_string_pretty(&fixtures_json).unwrap(),
    )
    .unwrap();
    let out = Command::new("go")
        .args(["run", "."])
        .current_dir(&dir)
        .output()
        .expect("`go` is required for the Go diff test (it is not skipped when missing)");
    assert!(
        out.status.success(),
        "go run failed:\n{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let run: GoRun = serde_json::from_slice(&out.stdout).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    run
}

/// One diff row.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Row {
    ty: String,
    field: String,
    generated: String,
    handwritten: String,
    /// What the Rust serde output has at this path.
    truth: String,
}

const ABSENT: &str = "(absent)";

fn show(v: Option<&Value>) -> String {
    v.map_or_else(|| ABSENT.to_string(), Value::to_string)
}

fn child<'a>(v: Option<&'a Value>, key: &str) -> Option<&'a Value> {
    v.and_then(|v| v.as_object()).and_then(|o| o.get(key))
}

/// Compare `gen` and `hand` at every path of `truth` ∪ `hand`. Keys only
/// the generated output has are returned in `gen_extra`.
fn diff(
    ty: &str,
    path: &str,
    truth: Option<&Value>,
    gen_v: Option<&Value>,
    hand: Option<&Value>,
    rows: &mut Vec<Row>,
    gen_extra: &mut Vec<String>,
) {
    let is_obj = |v: Option<&Value>| v.is_none_or(Value::is_object);
    let is_arr = |v: Option<&Value>| v.is_none_or(Value::is_array);
    let any_some = truth.is_some() || hand.is_some() || gen_v.is_some();
    let join = |k: &str| {
        if path.is_empty() {
            k.to_string()
        } else {
            format!("{path}.{k}")
        }
    };
    if any_some
        && is_obj(truth)
        && is_obj(gen_v)
        && is_obj(hand)
        && [truth, gen_v, hand]
            .iter()
            .any(|v| v.is_some_and(Value::is_object))
    {
        let mut keys = BTreeSet::new();
        for v in [truth, hand].into_iter().flatten() {
            keys.extend(v.as_object().unwrap().keys().cloned());
        }
        if let Some(g) = gen_v {
            for k in g.as_object().unwrap().keys() {
                if !keys.contains(k) {
                    gen_extra.push(format!("{ty}.{}", join(k)));
                }
            }
        }
        for k in keys {
            diff(
                ty,
                &join(&k),
                child(truth, &k),
                child(gen_v, &k),
                child(hand, &k),
                rows,
                gen_extra,
            );
        }
        return;
    }
    if any_some
        && is_arr(truth)
        && is_arr(gen_v)
        && is_arr(hand)
        && [truth, gen_v, hand]
            .iter()
            .any(|v| v.is_some_and(|x| x.as_array().is_some_and(|a| !a.is_empty())))
    {
        let len = [truth, gen_v, hand]
            .iter()
            .map(|v| v.and_then(Value::as_array).map_or(0, Vec::len))
            .max()
            .unwrap_or(0);
        for i in 0..len {
            fn at(v: Option<&Value>, i: usize) -> Option<&Value> {
                v.and_then(Value::as_array).and_then(|a| a.get(i))
            }
            diff(
                ty,
                &format!("{path}[{i}]"),
                at(truth, i),
                at(gen_v, i),
                at(hand, i),
                rows,
                gen_extra,
            );
        }
        return;
    }
    if gen_v != hand {
        rows.push(Row {
            ty: ty.to_string(),
            field: if path.is_empty() {
                "(value)".into()
            } else {
                path.to_string()
            },
            generated: show(gen_v),
            handwritten: show(hand),
            truth: show(truth),
        });
    }
}

struct Compared {
    rows: Vec<Row>,
    gen_extra: Vec<String>,
    /// Fixtures where the generated Go output differs from the Rust output.
    gen_mismatch: Vec<String>,
    errors: Vec<String>,
}

fn compare(fixtures: &[Fixture], run: &GoRun) -> Compared {
    let mut c = Compared {
        rows: Vec::new(),
        gen_extra: Vec::new(),
        gen_mismatch: Vec::new(),
        errors: Vec::new(),
    };
    let hand = hand_types();
    for f in fixtures {
        let r = run.results.iter().find(|r| r.label == f.label).unwrap();
        if !r.gen_err.is_empty() {
            c.errors
                .push(format!("{} (generated): {}", f.label, r.gen_err));
        }
        // Go → Rust: serde must decode the generated Go's output back to
        // the same value.
        if let (Some(back), Some(out)) = (f.back, r.gen_out.as_ref()) {
            match back(out) {
                Ok(v) if v == f.json => {}
                Ok(v) => c.gen_mismatch.push(format!(
                    "{}: serde decode of the generated Go output gives {v}, not {}",
                    f.label, f.json
                )),
                Err(e) => c.gen_mismatch.push(format!(
                    "{}: serde rejects the generated Go output {out}: {e}",
                    f.label
                )),
            }
        }
        if !hand.contains(f.ty) {
            if r.gen_out.as_ref() != Some(&f.json) {
                c.gen_mismatch.push(format!(
                    "{}: rust {} != generated {}",
                    f.label,
                    f.json,
                    show(r.gen_out.as_ref())
                ));
            }
            continue;
        }
        if !r.hand_err.is_empty() {
            c.rows.push(Row {
                ty: f.ty.into(),
                field: "(decode)".into(),
                generated: "ok".into(),
                handwritten: r.hand_err.clone(),
                truth: "ok".into(),
            });
            // The hand-written side has no output to compare field by field.
            if r.gen_out.as_ref() != Some(&f.json) {
                c.gen_mismatch.push(format!(
                    "{}: rust {} != generated {}",
                    f.label,
                    f.json,
                    show(r.gen_out.as_ref())
                ));
            }
            continue;
        }
        if r.gen_out.as_ref() != Some(&f.json) {
            c.gen_mismatch.push(format!(
                "{}: rust {} != generated {}",
                f.label,
                f.json,
                show(r.gen_out.as_ref())
            ));
        }
        // A hand-written type that marshals to `{}` (e.g. StreamPart, whose
        // fields are all `json:"-"`) drops the whole value: one row.
        let empty = r.hand_out.as_ref().is_some_and(|h| h == &json!({}));
        if empty && f.json.as_object().is_some_and(|o| !o.is_empty()) {
            if r.gen_out.as_ref() != Some(&f.json) {
                c.gen_mismatch
                    .push(format!("{}: rust {} != generated", f.label, f.json));
            }
            c.rows.push(Row {
                ty: f.ty.into(),
                field: "(all fields)".into(),
                generated: show(r.gen_out.as_ref()),
                handwritten: "{}".into(),
                truth: f.json.to_string(),
            });
            continue;
        }
        diff(
            f.ty,
            "",
            Some(&f.json),
            r.gen_out.as_ref(),
            r.hand_out.as_ref(),
            &mut c.rows,
            &mut c.gen_extra,
        );
    }
    c.rows.sort();
    c.rows.dedup_by(|a, b| a.ty == b.ty && a.field == b.field);
    c
}

/// One entry of `docs/plan/2.2-diff-go-verdicts.json`.
#[derive(serde::Deserialize, Debug, Clone)]
#[serde(deny_unknown_fields)]
struct Verdict {
    #[serde(rename = "type")]
    ty: String,
    field: String,
    verdict: String,
    /// Required; missing or empty fails the test.
    #[serde(default)]
    reason: Option<String>,
}

fn parse_verdicts(text: &str) -> Result<Vec<Verdict>, String> {
    serde_json::from_str(text).map_err(|e| format!("verdicts file: {e}"))
}

/// Every verdict problem: a row without an entry, an entry without a row
/// (orphan), an entry contradicting the Rust output, a value that is not
/// one of the two verdicts, a missing/empty `reason`, a duplicate entry.
fn verdict_problems(rows: &[Row], entries: &[Verdict]) -> Vec<String> {
    let mut problems = Vec::new();
    let mut seen = BTreeSet::new();
    for e in entries {
        if !seen.insert((e.ty.clone(), e.field.clone())) {
            problems.push(format!("duplicate verdict for {} | {}", e.ty, e.field));
        }
        if e.reason.as_deref().is_none_or(|r| r.trim().is_empty()) {
            problems.push(format!("verdict for {} | {} has no reason", e.ty, e.field));
        }
        if e.verdict != "generator bug" && e.verdict != "handwritten bug" {
            problems.push(format!(
                "bad verdict `{}` for {} | {}",
                e.verdict, e.ty, e.field
            ));
        }
        if !rows.iter().any(|r| r.ty == e.ty && r.field == e.field) {
            problems.push(format!(
                "orphan verdict for {} | {} (no such diff row)",
                e.ty, e.field
            ));
        }
    }
    for r in rows {
        match entries.iter().find(|e| e.ty == r.ty && e.field == r.field) {
            None => problems.push(format!("no verdict for {} | {}", r.ty, r.field)),
            Some(e)
                if (e.verdict == "generator bug" || e.verdict == "handwritten bug")
                    && e.verdict != expected_verdict(r) =>
            {
                problems.push(format!(
                    "verdict `{}` for {} | {} contradicts the Rust output {}",
                    e.verdict, r.ty, r.field, r.truth
                ));
            }
            Some(_) => {}
        }
    }
    problems
}

fn verdict_map(entries: &[Verdict]) -> BTreeMap<(String, String), String> {
    entries
        .iter()
        .map(|e| ((e.ty.clone(), e.field.clone()), e.verdict.clone()))
        .collect()
}

/// Replace `path` with `text` via a temp file in the same directory and a
/// rename, so no reader (another test, another `cargo test`) ever sees a
/// truncated or half-written file.
fn write_atomic(path: &Path, text: &str) {
    let tmp = path.with_extension(format!("md.tmp-{}", std::process::id()));
    std::fs::write(&tmp, text).unwrap();
    std::fs::rename(&tmp, path).unwrap();
}

/// Problem when the committed doc differs from `doc`.
fn doc_problem(committed: Option<&str>, doc: &str) -> Option<String> {
    (committed != Some(doc)).then(|| {
        "docs/plan/2.2-diff-go.md is out of date; run AIMUX_BLESS_DIFF=1 cargo test -p aimux-codegen --test wire_diff_go".to_string()
    })
}

fn expected_verdict(r: &Row) -> &'static str {
    if r.generated == r.truth {
        "handwritten bug"
    } else {
        "generator bug"
    }
}

fn cell(s: &str) -> String {
    format!("`{}`", s.replace('|', "\\|"))
}

fn render(
    fixtures: &[Fixture],
    run: &GoRun,
    rows: &[Row],
    v: &BTreeMap<(String, String), String>,
) -> String {
    let mut s = String::from(
        "<!-- Generated by tools/aimux-codegen/tests/wire_diff_go.rs; do not edit.\n     Regenerate: AIMUX_BLESS_DIFF=1 cargo test -p aimux-codegen --test wire_diff_go\n     Verdicts: docs/plan/2.2-diff-go-verdicts.json -->\n\n# 2.2: generated Go vs hand-written Go\n\n",
    );
    s.push_str("Each fixture is a real aimux-core value serialized with serde (the truth). It is decoded and re-marshaled by the generated Go (`aimux-codegen --emit go`) and by the hand-written `bindings/go/types.go` + `multimodal_types.go`. A row is a JSON path where the two outputs differ. The verdict says which side disagrees with the Rust output. The test also requires the generated output to equal the Rust output for every fixture.\n\n");
    s.push_str("## Fixtures\n\n| label | type | serde output |\n|---|---|---|\n");
    for f in fixtures {
        s.push_str(&format!(
            "| {} | {} | {} |\n",
            f.label,
            f.ty,
            cell(&f.json.to_string())
        ));
    }
    s.push_str("\nUntagged overlap: `image-result-overlap` has `\"images\":[]`, which is a valid `Base64(Vec<String>)` and a valid `Binary(Vec<Vec<u8>>)` (`ImageOutputs`, image_model.rs). serde picks the first declared variant. The generated Go picked: ");
    let picked: Vec<String> = run
        .variants
        .iter()
        .map(|(k, v)| format!("`{k}` → `{v}`"))
        .collect();
    s.push_str(&picked.join(", "));
    s.push_str(".\n\n## Diff\n\n| type | field | generated | handwritten | verdict |\n|---|---|---|---|---|\n");
    for r in rows {
        let verdict = v
            .get(&(r.ty.clone(), r.field.clone()))
            .map_or("(missing)", String::as_str);
        s.push_str(&format!(
            "| {} | {} | {} | {} | {verdict} |\n",
            r.ty,
            cell(&r.field),
            cell(&r.generated),
            cell(&r.handwritten)
        ));
    }
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    for r in rows {
        if let Some(x) = v.get(&(r.ty.clone(), r.field.clone())) {
            *counts.entry(x.clone()).or_default() += 1;
        }
    }
    s.push_str(&format!("\nRows: {}", rows.len()));
    for (k, n) in &counts {
        s.push_str(&format!("; {k}: {n}"));
    }
    s.push_str(".\n");
    let hand = hand_types();
    let gen_t = generated_types();
    let covered = hand.iter().filter(|t| gen_t.contains(*t)).count();
    s.push_str(&format!(
        "\n## Coverage\n\nHand-written types with a generated counterpart: {covered}, each with at least one fixture (test `every_hand_written_type_with_a_generated_counterpart_has_a_fixture`). Hand-written types with no generated counterpart: {}.\n",
        hand.iter()
            .filter(|t| !gen_t.contains(*t))
            .map(|t| format!("`{t}`"))
            .collect::<Vec<_>>()
            .join(", ")
    ));
    let only: Vec<&String> = gen_t.iter().filter(|t| !hand.contains(*t)).collect();
    s.push_str(&format!(
        "\n## Generated types with no hand-written counterpart ({})\n\n",
        only.len()
    ));
    for t in only {
        s.push_str(&format!("- `{t}`\n"));
    }
    s
}

/// One Go run over all fixtures, shared by the tests below.
fn shared() -> &'static (Vec<Fixture>, GoRun) {
    static RUN: std::sync::OnceLock<(Vec<Fixture>, GoRun)> = std::sync::OnceLock::new();
    RUN.get_or_init(|| {
        let f = fixtures();
        let r = run_go("shared", &f, |s| s);
        (f, r)
    })
}

fn gen_out(label: &str) -> (&'static Value, Value) {
    let (f, r) = shared();
    let fx = f.iter().find(|x| x.label == label).unwrap();
    let out = r
        .results
        .iter()
        .find(|x| x.label == label)
        .and_then(|x| x.gen_out.clone())
        .unwrap_or(Value::Null);
    (&fx.json, out)
}

#[test]
fn every_hand_written_type_with_a_generated_counterpart_has_a_fixture() {
    let f = fixtures();
    assert_eq!(uncovered(&f), Vec::<String>::new());
    // Mutation: dropping every fixture of one type is reported, by name.
    let without: Vec<Fixture> = f
        .into_iter()
        .filter(|x| x.ty != "VideoPollOptions")
        .collect();
    assert_eq!(uncovered(&without), vec!["VideoPollOptions".to_string()]);
}

/// (a) Both directions: serde JSON → Go decode → Go encode equals the serde
/// output, and serde decodes the Go output back to the same value.
#[test]
fn decode_and_encode_directions_match_serde() {
    let (f, r) = shared();
    let c = compare(f, r);
    assert!(c.errors.is_empty(), "{:#?}", c.errors);
    assert!(c.gen_mismatch.is_empty(), "{:#?}", c.gen_mismatch);
    let with_back = f.iter().filter(|x| x.back.is_some()).count();
    assert!(
        with_back > 100,
        "only {with_back} fixtures checked Go → serde"
    );
}

/// (b) A field Rust writes as `null` stays `null` in the generated Go.
#[test]
fn null_fields_stay_null() {
    let (truth, out) = gen_out("chat-completion-chunk");
    assert_eq!(truth["choices"][0]["finish_reason"], Value::Null);
    assert!(
        out["choices"][0]
            .as_object()
            .unwrap()
            .contains_key("finish_reason")
    );
    assert_eq!(out["choices"][0]["finish_reason"], Value::Null);
    let (truth, out) = gen_out("chat-completion");
    assert_eq!(truth["choices"][0]["message"]["content"], Value::Null);
    assert_eq!(out, *truth);
}

/// (c) Tri-state (`BooleanCriteria.true`): absent, `null`, and a value
/// round-trip distinctly; Nullable (`ChatCompletionMessage.content`): null
/// and present.
#[test]
fn tri_state_and_nullable_round_trip() {
    for (label, expected) in [
        ("tri-state-absent", json!({})),
        ("tri-state-null", json!({"true": null})),
        ("tri-state-present", json!({"true": "yes", "false": null})),
    ] {
        let (truth, out) = gen_out(label);
        assert_eq!(truth, &expected, "{label}: serde");
        assert_eq!(out, expected, "{label}: generated Go");
    }
    let (_, out) = gen_out("chat-completion-answer");
    assert_eq!(out["choices"][0]["message"]["content"], "It is sunny.");
}

/// (d) A proxied type and a generic instantiation against serde output.
#[test]
fn proxied_and_generic_types_match_serde() {
    for label in [
        "proxy-aimux-error",
        "proxy-size",
        "cov-StreamPart-ToolCall",
        "cov-StreamPart-ToolApprovalRequest",
        "cov-StreamPart-ReasoningFile",
    ] {
        let (truth, out) = gen_out(label);
        assert_eq!(&out, truth, "{label}");
    }
    assert_eq!(gen_out("proxy-size").0, &json!("1024x768"));
    assert_eq!(gen_out("proxy-aimux-error").0["name"], "AI_NoSuchToolError");
}

#[test]
fn generated_go_matches_rust_and_diff_doc_is_current() {
    let fixtures = fixtures();
    let run = run_go("main", &fixtures, |s| s);
    let c = compare(&fixtures, &run);
    assert!(c.errors.is_empty(), "generated Go failed: {:#?}", c.errors);
    assert!(
        c.gen_mismatch.is_empty(),
        "generator bugs (generated Go != Rust serde output): {:#?}",
        c.gen_mismatch
    );
    assert!(
        c.gen_extra.is_empty(),
        "generated-only keys: {:?}",
        c.gen_extra
    );
    assert_eq!(
        run.variants.get("image-result-overlap").map(String::as_str),
        Some("Base64"),
        "untagged overlap must follow declaration order"
    );
    assert_eq!(
        run.variants.get("image-result-binary").map(String::as_str),
        Some("Binary")
    );

    let vpath = workspace().join("docs/plan/2.2-diff-go-verdicts.json");
    let entries = parse_verdicts(&std::fs::read_to_string(&vpath).unwrap()).unwrap();
    let mut problems = verdict_problems(&c.rows, &entries);
    let doc = render(&fixtures, &run, &c.rows, &verdict_map(&entries));
    let dpath = workspace().join("docs/plan/2.2-diff-go.md");
    if std::env::var_os("AIMUX_BLESS_DIFF").is_some() {
        write_atomic(&dpath, &doc);
    } else {
        problems.extend(doc_problem(
            std::fs::read_to_string(&dpath).ok().as_deref(),
            &doc,
        ));
    }
    assert!(problems.is_empty(), "{problems:#?}");
}

/// Mutation: rename one wire name in the generated Go (`ToolCall.toolCallId`
/// → `toolCallID`). The comparison reports exactly that one row, and the
/// generator check flags it.
#[test]
fn mutated_wire_name_is_reported_as_exactly_one_row() {
    let fixtures: Vec<Fixture> = fixtures()
        .into_iter()
        .filter(|f| f.label == "tool-call")
        .collect();
    let base = compare(&fixtures, &run_go("base", &fixtures, |s| s));
    let mutated_run = run_go("mutated", &fixtures, |s| {
        let start = s.find("\ntype ToolCall struct {").expect("ToolCall struct");
        let end = start + s[start..].find("\n}\n").unwrap();
        let block = &s[start..end];
        let from = "`json:\"toolCallId\"`";
        assert!(block.contains(from), "{block}");
        format!(
            "{}{}{}",
            &s[..start],
            block.replacen(from, "`json:\"toolCallID\"`", 1),
            &s[end..]
        )
    });
    let mutated = compare(&fixtures, &mutated_run);
    let new: Vec<&Row> = mutated
        .rows
        .iter()
        .filter(|r| !base.rows.contains(r))
        .collect();
    assert_eq!(
        new,
        vec![&Row {
            ty: "ToolCall".into(),
            field: "toolCallId".into(),
            generated: ABSENT.into(),
            handwritten: "\"call_1\"".into(),
            truth: "\"call_1\"".into(),
        }]
    );
    assert_eq!(expected_verdict(new[0]), "generator bug");
    assert_eq!(mutated.gen_extra, vec!["ToolCall.toolCallID".to_string()]);
    // Both directions catch it: Go output != serde output, and serde
    // rejects the Go output (missing `toolCallId`).
    assert_eq!(mutated.gen_mismatch.len(), 2, "{:?}", mutated.gen_mismatch);
    assert!(
        mutated
            .gen_mismatch
            .iter()
            .all(|m| m.starts_with("tool-call:"))
    );
    assert!(mutated.gen_mismatch[0].contains("missing field `toolCallId`"));
}

/// Mutation proof for each verdict/doc check, on the real rows and the
/// committed verdicts file.
#[test]
fn verdict_and_doc_checks_each_catch_their_mutation() {
    let (f, r) = shared();
    let c = compare(f, r);
    let text =
        std::fs::read_to_string(workspace().join("docs/plan/2.2-diff-go-verdicts.json")).unwrap();
    let entries = parse_verdicts(&text).unwrap();
    assert_eq!(verdict_problems(&c.rows, &entries), Vec::<String>::new());
    let target = c
        .rows
        .iter()
        .find(|r| r.ty == "ImageResult" && r.field == "warnings")
        .unwrap();
    let at = entries
        .iter()
        .position(|e| e.ty == target.ty && e.field == target.field)
        .unwrap();

    // Missing verdict: drop the entry.
    let mut m = entries.clone();
    m.remove(at);
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["no verdict for ImageResult | warnings"]
    );
    // Contradicting verdict.
    let mut m = entries.clone();
    m[at].verdict = "generator bug".into();
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict `generator bug` for ImageResult | warnings contradicts the Rust output []"]
    );
    // Orphan verdict: an entry for a row that does not exist.
    let mut m = entries.clone();
    let mut orphan = m[at].clone();
    orphan.field = "nonexistent".into();
    m.push(orphan);
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["orphan verdict for ImageResult | nonexistent (no such diff row)"]
    );
    // Missing `reason`: removed from the JSON text, and empty.
    let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
    v[at].as_object_mut().unwrap().remove("reason");
    let m = parse_verdicts(&v.to_string()).unwrap();
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict for ImageResult | warnings has no reason"]
    );
    let mut m = entries.clone();
    m[at].reason = Some("  ".into());
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict for ImageResult | warnings has no reason"]
    );
    // Stale doc. This test never reads docs/plan/2.2-diff-go.md: that file
    // is owned by generated_go_matches_rust_and_diff_doc_is_current, which
    // may rewrite it (AIMUX_BLESS_DIFF=1) while this test runs in parallel.
    // The mutation works on an in-memory scratch copy of the rendered doc.
    let doc = render(f, r, &c.rows, &verdict_map(&entries));
    let scratch = doc.clone();
    assert_eq!(doc_problem(Some(&scratch), &doc), None);
    let stale = scratch.replacen("handwritten bug", "generator bug", 1);
    assert_ne!(stale, scratch);
    assert!(doc_problem(Some(&stale), &doc).is_some());
    assert!(doc_problem(None, &doc).is_some());
}
